"""Appends section 8 (E2 320-px extension, E1 warm-up/rotated extension, E2 per-process service means) to SUMMARY.md from e8_summary.json.
Usage: python e8_write.py OUTDIR"""
import sys, os, json, time, glob, numpy as np
OUT = sys.argv[1]; E = json.load(open(OUT + '/e8_summary.json')); S = []
def table(head, rows): return '| ' + ' | '.join(head) + ' |\n|' + '---|' * len(head) + '\n' + '\n'.join('| ' + ' | '.join(str(c) for c in r) + ' |' for r in rows) + '\n'
f1 = lambda x: f'{x:.1f}'; f3 = lambda x: f'{x:.3f}'
S.append(f'\n## 8. Extensions (added {time.strftime("%Y-%m-%d %H:%M %Z")}; same node, core 2, one torch thread, same guards; no earlier output modified)\n')
# ---- A
A = E['A']; S.append('### 8A. E2 at 320 px, Adaptive, deadline-aware, N = 38, 39, 40 (new) alongside the earlier 41-44 (600 s, 2 repeats, ms)\n')
rows = [[r['N'], r['rep'], 'new' if r['new'] else 'earlier', r['jobs'], f3(r['util']), f"{r['miss']:.2f} ({r['n_miss']})", f1(r['resp_p99_ms']), f1(r['resp_max_ms']), f1(r['service_mean_ms']), f1(r['service_max_ms']), f3(r['sim_util']) if r['sim_util'] is not None else '-', f"{r['sim_miss']:.2f}" if r['sim_miss'] is not None else '-',
         f1(r['sim_resp_p99_ms']) if r['sim_resp_p99_ms'] else '-', f1(r['sim_resp_max_ms']) if r['sim_resp_max_ms'] else '-', f"{r['agree']:.1f}", ' '.join(map(str, r['miss_per_60s'])), ' '.join(r['load_end'])] for r in A['rows']]
S.append(table(['N', 'rep', 'run', 'jobs', 'util', 'miss % (n)', 'resp p99', 'resp max', 'service mean', 'service max', 'sim util', 'sim miss %', 'sim p99', 'sim max', 'decision agree %', 'misses per 60-s window', 'load end'], rows))
S.append(f"Largest N with zero misses in both repeats (deadline-aware, 320 px, N tested {', '.join(map(str, A['N_tested']))}): **live {A['live_max_zero_miss_all_repeats']}** (zero-miss N: {', '.join(map(str, A['zero_miss_N'])) or 'none'}) vs simulated N* = {A['sim_nstar']} (simulated zero misses at {', '.join(map(str, A['sim_zero_miss']))} within the tested range).\n")
# ---- B
if 'B' in E:
    B = E['B']; R = B['runs']; VIDS = list(next(iter(R.values()))['per_clip_median']); S.append('### 8B. E1 extension: five fresh e1_profile2.py processes, 640 px / 1 thread only, 120-s discarded back-to-back warm-up over all clips, clip order rotated by one position per run (frames 11+ of every clip; ms)\n')
    rows = [[k, ' > '.join(v[:4] for v in r['order']), r['warmup']['jobs'], f1(r['warmup']['mean_ms']), f1(r['mean']), f1(r['p50']), f1(r['p95']), f1(r['p99']), f1(r['p999']), f1(r['max']), f1(r['max_all_frames']), f"{100*r['sys_share_total']:.1f}", f"{r['miss12']:.2f} / {r['miss15']:.2f} / {r['miss30']:.2f}", r['steal'], ' '.join(r['load'][1])] for k, r in R.items()]
    p = B['pooled']; rows.append(['pooled', '', '', '', f1(p['mean']), f1(p['p50']), f1(p['p95']), f1(p['p99']), f1(p['p999']), f1(p['max']), '', '', f"{p['miss12']:.2f} / {p['miss15']:.2f} / {p['miss30']:.2f}", '', ''])
    S.append(table(['run', 'clip order (first 4 chars)', 'warm-up jobs', 'warm-up mean', 'mean', 'p50', 'p95', 'p99', 'p99.9', 'max', 'max all frames', 'system-time share %', 'miss % 12 / 15 / 30 fps', 'steal', 'load end'], rows))
    rows = [[k] + [f"{r['per_clip_median'][v]:.1f} ({100*r['sys_share'][v]:.1f} %)" + (' *' if v == r['first_clip'] else '') for v in VIDS] for k, r in R.items()]
    ref = B['reference_e1_per_clip_median']; rows += [[f'E1 {k}'] + [f"{ref[k][v]:.1f}" + (' *' if v == 'one-by-one' else '') for v in VIDS] for k in ref]
    S.append('Per-clip median service time (system-time share of that clip\'s configuration in parentheses; * = first clip timed in that process). E1 rows: the original runs 1-5 (no warm-up, fixed order, one-by-one first).\n\n' + table(['run'] + VIDS, rows))
    fm = [r['first_clip_median'] for r in R.values()]; fs = [r['first_clip_sys_share'] for r in R.values()]; om = [np.mean([m for v, m in r['per_clip_median'].items() if v != r['first_clip']]) for r in R.values()]
    xs = np.array([100 * r['sys_share_total'] for r in R.values()]); ys = np.array([r['mean'] for r in R.values()]); b, a0 = np.polyfit(xs, ys, 1); cc = np.corrcoef(xs, ys)[0, 1]
    S.append(f"Is the slow first configuration gone? The *first-configuration* effect of the original runs (one-by-one first, median about 58 ms with 11-16 % system time, the other clips 47-49 ms) does not recur: the first timed clip of each warmed-up process has a median of {', '.join(f1(x) for x in fm)} ms with system-time shares of {', '.join(f'{100*x:.1f}' for x in fs)} %, and it is never slower than the other clips of the same process ({', '.join(f1(x) for x in om)} ms). "
             f"What the warm-up and rotation reveal instead is a *process-level* state: runs 1 and 5 ran every clip at 48-51 ms with 2-5 % system time, runs 2 and 3 ran every clip at 52-56 ms with 8-10 % system time, and run 4 switched from 49 ms / 1 % on its first clip to 53-56 ms / 6-9 % afterwards (per-clip table). Across the five processes the mean service time follows the system-time share almost linearly (mean = {a0:.1f} + {b:.2f} x sys-share-%, r = {cc:.2f}). In the original E1 runs the same state is visible in the people clip (second configuration, median 54-58 ms in runs 2-5), so the earlier description as a first-configuration warm-up effect was incomplete: processes start in the high-system-time state, most leave it within minutes, some stay in it or re-enter it. "
             f"The state changes the mean by up to about 5 ms but not the maximum (72.5-81.5 ms in the original runs, {', '.join(f1(r['max']) for r in R.values())} ms here), so C_max, k_min and the deadline-miss rates are unaffected; the miss rate at 15 fps rises with the mean (0.03-0.35 %). The frame-0 transient on store-aisle (101-113 ms in E1) is also gone with warm-up: frame-0 service times " + '; '.join(f"{v}: " + ', '.join(f1(r['per_clip_frame0'][v]) for r in R.values()) for v in ['store-aisle', 'car-lot']) + ' ms, i.e. that transient was tied to the first inference after decoding and allocating a new clip, which the pre-decoded warm-up layout removes.\n')
    S.append(f"Pooled over the five warm-up runs (frames 11+): mean {p['mean']:.1f}, p50 {p['p50']:.1f}, p95 {p['p95']:.1f}, p99 {p['p99']:.1f}, p99.9 {p['p999']:.1f}, max {p['max']:.1f} ms; original E1 runs 1-5 pooled: mean 51.5, p50 48.4, p95 60.1, p99 67.1, p99.9 71.2, max 81.5 ms.\n")
else: S.append('### 8B. not available (e1b stage did not complete).\n')
# ---- C
C = E['C']; S.append('### 8C. Per-process mean detector service time of the E2 640-px runs (ms; one fresh process per run, sorted)\n')
rows = [[r['file'].replace('live_', '').replace('.json', '') + (f" ({r['policy']})" if r['N'] == 1 else ''), r['N'], r['jobs'], f1(r['service_mean']), f1(r['service_p50']), f1(r['service_p99']), f1(r['service_max']), f1(r['first120_mean']) if r['first120_mean'] else '-', f1(r['rest_mean']) if r['rest_mean'] else '-', f"{r['miss']:.2f}", time.strftime('%H:%M', time.localtime(r['start']))] for r in C['rows']]
S.append(table(['run', 'N', 'jobs', 'service mean', 'p50', 'p99', 'max', 'mean first 120 s', 'mean rest', 'miss %', 'start'], rows))
lo, hi = C['group_low'], C['group_high']; m = np.array(C['sorted_means'])
S.append(f"Sorted multi-camera means (24 processes): {', '.join(f1(x) for x in m)}. Thirteen processes lie at 47.9-50.7 ms, nine at 53.8-55.9 ms, and two in between (51.5, 52.8 ms); the largest gap between neighbours is {C['largest_gap_ms']:.1f} ms ({C['gap_between'][0]:.1f} to {C['gap_between'][1]:.1f}) against a next-largest gap of {C['max_other_gap']:.1f} ms, so the split is suggestive of two groups but not clean by a gap criterion alone. "
         f"The level is a property of the process rather than of N or policy: each policy has runs on both levels, and for three (policy, N) pairs the two repeats of the same N fall on different levels (adaptive 16/8 N = 14: 49.5 vs 54.9; deadline-aware N = 13: 49.3 vs 53.8 and N = 14: 48.3 vs 54.2 ms); the levels are interleaved over the 4.6 h of runs, so it is not a time-of-day effect. Within a run the level is mostly stable (first-120-s and remaining means within 0.6 ms in 15 of 24 runs), with a largest shift of 3.2 ms (adaptive 16/8, N = 13, repeat 1), consistent with the mid-run state switch seen in 8B run 4. Together with 8B, where the same two levels appear with 2-5 % vs 8-10 % system time, the two groups are best read as processes outside vs inside the high-page-fault state; live2.py did not record per-process system time, so this attribution for E2 is by analogy. "
         f"Consequence for E2: a process in the high state carries about 5 ms (10 %) more service time per job, which is the utilisation margin at N*, and the runs that missed deadlines at N* are high-level processes (fixed stride 8, N = 12: 54.2 ms with 4.9 % misses vs 52.8 ms with none; deadline-aware N = 14: 54.2 ms with 1.9 % misses vs 48.3 ms with none).\n")
open(OUT + '/SUMMARY.md', 'a').write('\n'.join(S)); print('appended section 8')
